// Adaptador do Trigger (uso real: chamado via toolWorkflow pelos especialistas,
// T11). Com inputSource="workflowInputs" (3 campos declarados), o Trigger já
// entrega id_maquina/grandeza/janela_min como campos de topo -- este nó só
// uniformiza os nomes ("_bruto") para o nó "Validar Entrada", que é
// compartilhado com o caminho do Webhook de teste, e marca via_webhook=false.
const t = $('Trigger').first().json;
return [{
  json: {
    id_maquina_bruto: t.id_maquina,
    grandeza_bruto: t.grandeza,
    janela_min_bruto: t.janela_min,
    via_webhook: false,
  },
}];

// Adaptador do Webhook de TESTE (n8n/nodes-catalog.md documenta este webhook
// como "só teste": permite chamar exatamente o mesmo caminho do tool sem
// precisar de um AI Agent/toolWorkflow no meio, útil para tests/smoke_*.js).
// Body esperado: {id_maquina, grandeza, janela_min}.
const w = $('Webhook Teste').first().json;
const body = (w.body && typeof w.body === 'object' && !Array.isArray(w.body)) ? w.body : {};
return [{
  json: {
    id_maquina_bruto: body.id_maquina,
    grandeza_bruto: body.grandeza,
    janela_min_bruto: body.janela_min,
    via_webhook: true,
  },
}];

// Nó compartilhado pelos dois caminhos de entrada (Trigger e Webhook de
// teste). NUNCA consulta o banco se a entrada for inválida -- é a defesa
// contra prompt injection / SQL injection via o parâmetro "grandeza" (ex.:
// "x; DROP TABLE leituras"), que não bate com a lista fixa depois de
// normalizado e cai direto em ok:false, sem passar pelo nó MySQL.

const GRANDEZAS_VALIDAS = ['temperatura', 'vibracao', 'corrente', 'taxa_producao', 'fator_potencia', 'eficiencia'];
const ID_REGEX = /^[A-Z0-9_]{3,32}$/; // igual a config/limiares.json::id_maquina_regex

// Normaliza acentos/maiúsculas/espaços: "Vibração" -> "vibracao", "Fator de Potência" -> "fator_de_potencia".
// (cobre o caso pedido no ticket -- "Vibração" -> "vibracao" -- sem exigir do
// chamador que já mande a grafia exata usada no banco.)
function normalizarGrandeza(raw) {
  if (typeof raw !== 'string') return '';
  return raw
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .trim()
    .toLowerCase()
    .replace(/\s+/g, '_');
}

const entrada = $input.first().json;
const via_webhook = !!entrada.via_webhook;

const idBruto = entrada.id_maquina_bruto;
const grandezaNormalizada = normalizarGrandeza(entrada.grandeza_bruto);

const erros = [];

if (typeof idBruto !== 'string' || !ID_REGEX.test(idBruto)) {
  erros.push(`id_maquina inválido: "${String(entrada.id_maquina_bruto)}". Use letras maiúsculas, números e "_", de 3 a 32 caracteres (ex.: MOTOR_01).`);
}

if (!GRANDEZAS_VALIDAS.includes(grandezaNormalizada)) {
  erros.push(`grandeza inválida: "${String(entrada.grandeza_bruto)}". Use uma das grandezas suportadas (veja grandezas_validas).`);
}

// janela_min: ausente/vazio -> default 120. Presente -> precisa ser inteiro 10..1440.
let janela_min = 120;
const janelaBruta = entrada.janela_min_bruto;
const janelaAusente = janelaBruta === undefined || janelaBruta === null || janelaBruta === '';
if (!janelaAusente) {
  const n = Number(janelaBruta);
  if (!Number.isFinite(n) || !Number.isInteger(n) || n < 10 || n > 1440) {
    erros.push(`janela_min inválida: "${String(janelaBruta)}". Use um número inteiro de minutos entre 10 e 1440 (padrão 120).`);
  } else {
    janela_min = n;
  }
}

if (erros.length) {
  return [{
    json: {
      ok: false,
      erro: erros.join(' '),
      grandezas_validas: GRANDEZAS_VALIDAS,
      via_webhook,
    },
  }];
}

return [{
  json: {
    ok: true,
    id_maquina: idBruto,
    grandeza: grandezaNormalizada,
    janela_min,
    via_webhook,
  },
}];

// Lê config/limiares.json::tendencia (fonte única dos limiares -- não
// duplicar os números 15/6 aqui "a seco"; se um dia mudarem, este nó já lê o
// valor novo sem precisar editar workflow). Fallback local só existe para o
// caso (não esperado) de o arquivo não abrir -- nunca deixa a tool quebrar
// por causa disso.
let limiares;
try {
  const buf = await this.helpers.getBinaryDataBuffer(0, 'data');
  limiares = JSON.parse(buf.toString('utf8'));
} catch (e) {
  limiares = { tendencia: { variacao_percentual_para_escalar: 15, amostras_minimas: 6 } };
}
const limiarEscalar = (limiares.tendencia && limiares.tendencia.variacao_percentual_para_escalar) ?? 15;
const amostrasMinimas = (limiares.tendencia && limiares.tendencia.amostras_minimas) ?? 6;

function round2(n) {
  return Math.round(n * 100) / 100;
}
function num2(v) {
  return (v === null || v === undefined) ? null : round2(Number(v));
}

const row = $('Buscar Historico').first().json;
const entrada = $('Validar Entrada').first().json;

const amostras = Number(row.amostras) || 0;
const media = num2(row.media);
const desvio_padrao = num2(row.desvio_padrao);
const minimo = num2(row.minimo);
const maximo = num2(row.maximo);
const primeiro = num2(row.primeiro);
const ultimo = num2(row.ultimo);
const variacao_percentual = num2(row.variacao_percentual);

const suficiente = amostras >= amostrasMinimas;

let tendencia = 'estavel';
if (variacao_percentual !== null) {
  if (variacao_percentual >= 5) tendencia = 'alta';
  else if (variacao_percentual <= -5) tendencia = 'baixa';
}

let interpretacao;
if (amostras === 0) {
  interpretacao = 'Sem histórico na janela.';
} else if (!suficiente) {
  interpretacao = `Variação de ${variacao_percentual === null ? 'n/d' : variacao_percentual + ' %'} em ${entrada.janela_min} min, mas apenas ${amostras} amostra(s) (mínimo ${amostrasMinimas} para avaliar tendência).`;
} else if (tendencia === 'estavel') {
  interpretacao = `Estável: variação de ${variacao_percentual} % em ${entrada.janela_min} min (${amostras} amostras), abaixo do limiar de ${limiarEscalar} % para escalar severidade.`;
} else {
  const rotulo = tendencia === 'alta' ? 'Alta' : 'Queda';
  const varAbs = Math.abs(variacao_percentual);
  const atingeLimiar = varAbs >= limiarEscalar;
  interpretacao = `${rotulo} de ${varAbs} % em ${entrada.janela_min} min (${amostras} amostras): ` +
    (atingeLimiar
      ? `tendência de ${tendencia} significativa (≥ ${limiarEscalar} %).`
      : `variação abaixo do limiar de ${limiarEscalar} % para escalar severidade.`);
}

const resultado = {
  ok: true,
  id_maquina: entrada.id_maquina,
  grandeza: entrada.grandeza,
  janela_min: entrada.janela_min,
  amostras,
  media,
  desvio_padrao,
  minimo,
  maximo,
  primeiro,
  ultimo,
  variacao_percentual,
  tendencia,
  suficiente_para_tendencia: suficiente,
  interpretacao,
};

return [{ json: { via_webhook: entrada.via_webhook, resultado } }];

// Entrada inválida: NUNCA consultou o banco (ver "Validar Entrada"). Devolve
// um erro claro para o LLM decidir o que fazer (ex.: pedir ajuda humana),
// nunca inventa números.
const entrada = $input.first().json;
const resultado = {
  ok: false,
  erro: entrada.erro,
  grandezas_validas: entrada.grandezas_validas,
};
return [{ json: { via_webhook: entrada.via_webhook, resultado } }];

// Caminho real (chamado como tool por um AI Agent via toolWorkflow, T11):
// nenhum nó de Webhook envolvido nesta execução. A saída deste nó (o objeto
// "resultado", já sem o campo interno via_webhook) é o que o toolWorkflow lê
// como retorno da tool ("olha no último nó para a resposta").
return [{ json: $input.first().json.resultado }];
